"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raise the CPU limit of the 'api' container to 750m to alleviate throttling caused by the new version's higher CPU usage.",
  "rationale": "The new version (4.2.0) uses 0.495 CPU (99% of 0.5 limit) and is throttled 64% of the time. The previous version (4.1.3) had 8% throttling. The rollout changed the image, and the new version's usage exceeds the limit, causing throttling. Raising the limit to 750m (1.5x current) should clear the throttling.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-revision_health", "ev-rollout_history"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "rollout_changed_the_app", "throttling_came_with_rollout"]
